def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    colors = {v for row in grid for v in row} - {7}
    candidates = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for top in range(h):
            for left in range(w):
                if grid[top][left] != color:
                    continue
                for bottom in range(top + 1, h):
                    for right in range(left + 1, w):
                        if all(grid[top][c] == color and grid[bottom][c] == color for c in range(left, right + 1)) and all(grid[r][left] == color and grid[r][right] == color for r in range(top, bottom + 1)):
                            candidates.append((top, left, bottom, right))
    if not candidates:
        return g
    top, left, bottom, right = min(candidates)
    for c in (left, right):
        if top > 0: g[top - 1][c] = 2
        if bottom + 1 < h: g[bottom + 1][c] = 2
    for r in (top, bottom):
        if left > 0: g[r][left - 1] = 2
        if right + 1 < w: g[r][right + 1] = 2
    return g
